export function getTodosTemas(): TemaTeologico[] {
  return temas;
}

export function getTemasPorCategoria(categoria: string): TemaTeologico[] {
  return temas.filter(t => t.categoria === categoria);
}

export function getTemaPorId(id: string): TemaTeologico | undefined {
  return temas.find(t => t.id === id);
}

export function getEstatisticasTeologia() {
  const categorias = [...new Set(temas.map(t => t.categoria))];
  return {
    totalTemas: temas.length,
    totalCategorias: categorias.length,
    categorias: categorias.map(cat => ({
      nome: cat,
      quantidade: temas.filter(t => t.categoria === cat).length
    }))
  };
}
